description:
Implement a `useIsFirstRender` hook that returns `true` on the very first render and `false` on every subsequent render. Use a ref — do NOT use state (state would trigger an extra render).

**Example:**
```tsx
const isFirstRender = useIsFirstRender();
if (!isFirstRender) trackPageView();
```

starter_code:
import { useRef, useEffect } from 'react';

export function useIsFirstRender(): boolean {
  // your code here
}

test_suite:
test('returns true on first render', () => {
  const { result } = renderHook(() => useIsFirstRender());
  expect(result.current).toBe(true);
});

test('returns false on second render', () => {
  const { result, rerender } = renderHook(() => useIsFirstRender());
  rerender();
  expect(result.current).toBe(false);
});

test('returns false on every subsequent render', () => {
  const { result, rerender } = renderHook(() => useIsFirstRender());
  rerender();
  rerender();
  rerender();
  expect(result.current).toBe(false);
});

// __hidden__
test('independent instances do not share state', () => {
  const { result: r1 } = renderHook(() => useIsFirstRender());
  const { result: r2, rerender: rerender2 } = renderHook(() => useIsFirstRender());
  rerender2();
  expect(r1.current).toBe(true);
  expect(r2.current).toBe(false);
});

solution:
import { useRef } from 'react';

export function useIsFirstRender(): boolean {
  const isFirst = useRef(true);
  if (isFirst.current) {
    isFirst.current = false;
    return true;
  }
  return false;
}
